/// In-memory [`ExportArtifactStore`] capturing every uploaded object so a test
/// can assert on the generated bytes and content type without any live S3.
#[derive(Debug, Default)]
struct MockStore {
    objects: Mutex<HashMap<String, (Vec<u8>, String)>>,
}

#[async_trait]
impl ExportArtifactStore for MockStore {
    async fn put(
        &self,
        key: &str,
        bytes: Vec<u8>,
        content_type: &str,
    ) -> Result<(), StorageError> {
        self.objects
            .lock()
            .unwrap()
            .insert(key.to_string(), (bytes, content_type.to_string()));
        Ok(())
    }

    async fn presign_get(
        &self,
        key: &str,
        _ttl_secs: Option<u64>,
    ) -> Result<String, StorageError> {
        if self.objects.lock().unwrap().contains_key(key) {
            Ok(format!("https://mock.example/{key}?sig=abc"))
        } else {
            Err(StorageError::Request("object not found".into()))
        }
    }

    async fn get(&self, key: &str) -> Result<Vec<u8>, StorageError> {
        self.objects
            .lock()
            .unwrap()
            .get(key)
            .map(|(bytes, _)| bytes.clone())
            .ok_or_else(|| StorageError::Request(format!("object '{key}' not found")))
    }
}

impl MockStore {
    /// Seed a raw object (e.g. a `file`-field blob) so the ZIP bundle path can
    /// pull it back out via [`ExportArtifactStore::get`].
    fn seed_object(&self, key: &str, bytes: Vec<u8>, content_type: &str) {
        self.objects
            .lock()
            .unwrap()
            .insert(key.to_string(), (bytes, content_type.to_string()));
    }
}

// ---------------------------------------------------------------------------
// Harness
// ---------------------------------------------------------------------------

fn make_claims(roles: &[&str]) -> Claims {
    Claims {
        sub: "user:test-user".to_string(),
        roles: roles.iter().map(|r| r.to_string()).collect(),
        perms: vec![],
        exp: 9_999_999_999,
        iat: None,
        jti: None,
        iss: None,
        aud: None,
        email: None,
        username: None,
        custom: HashMap::new(),
    }
}

/// Claims for a specific subject, same shape as [`make_claims`] otherwise.
fn make_claims_with_sub(sub: &str, roles: &[&str]) -> Claims {
    Claims {
        sub: sub.to_string(),
        ..make_claims(roles)
    }
}

async fn build_state(
    backend: Arc<dyn DynForgeBackend>,
    registry: HashMap<String, SchemaDefinition>,
) -> AppState<SchemaForgeConfig> {
    use acton_service::service_builder::ServiceBuilder;

    let config = Config::<SchemaForgeConfig>::default();
    let service = ServiceBuilder::new()
        .with_config(config)
        .with_actor::<ForgeActor>()
        .with_actor::<schema_forge_acton::HookDispatchActor>()
        .with_actor::<ExportJobActor>()
        .with_actor::<schema_forge_acton::ExportRateLimiter>()
        .build();

    let forge_handle = service
        .state()
        .actor::<ForgeActor>()
        .expect("ForgeActor not registered");

    let (tx, rx) = oneshot::channel();
    forge_handle
        .send(InitForge {
            registry,
            backend,
            tenant_config: None,
            record_access_policy: None,
            hook_dispatcher: None,
            storage_registry: schema_forge_acton::storage::StorageRegistry::default(),
            policy_store: None,
            custom_policies_dir: None,
            reply: ReplyChannel::new(tx),
        })
        .await;
    tokio::time::timeout(Duration::from_secs(5), rx)
        .await
        .expect("InitForge timeout")
        .expect("InitForge channel dropped");

    service.state().clone()
}

fn app_with_claims(state: AppState<SchemaForgeConfig>, claims: Claims) -> Router {
    forge_routes()
        .layer(axum::middleware::from_fn(
            move |mut req: axum::extract::Request, next: axum::middleware::Next| {
                let claims = claims.clone();
                async move {
                    req.extensions_mut().insert(claims);
                    next.run(req).await
                }
            },
        ))
        .with_state(state)
}

async fn raw_request(
    app: &Router,
    method: Method,
    path: &str,
    body: Option<serde_json::Value>,
) -> (StatusCode, serde_json::Value) {
    let body = match body {
        Some(v) => Body::from(serde_json::to_vec(&v).unwrap()),
        None => Body::empty(),
    };
    let request = Request::builder()
        .method(method)
        .uri(path)
        .header("content-type", "application/json")
        .body(body)
        .unwrap();
    let response = app.clone().oneshot(request).await.unwrap();
    let status = response.status();
    let bytes = response.into_body().collect().await.unwrap().to_bytes();
    let json = if bytes.is_empty() {
        serde_json::Value::Null
    } else {
        serde_json::from_slice(&bytes).unwrap_or(serde_json::Value::Null)
    };
    (status, json)
}

fn exportable_field(name: &str) -> FieldDefinition {
    FieldDefinition::with_annotations(
        FieldName::new(name).unwrap(),
        FieldType::Text(TextConstraints::unconstrained()),
        vec![],
        vec![FieldAnnotation::Exportable { flatten: None }],
    )
}

fn plain_field(name: &str) -> FieldDefinition {
    FieldDefinition::new(
        FieldName::new(name).unwrap(),
        FieldType::Text(TextConstraints::unconstrained()),
    )
}

/// `Subject`: `name` + `notes` exportable, `secret` readable-but-not-exportable.
fn export_schema() -> SchemaDefinition {
    SchemaDefinition::new(
        SchemaId::new(),
        SchemaName::new("Subject").unwrap(),
        vec![
            exportable_field("name"),
            exportable_field("notes"),
            plain_field("secret"),
        ],
        vec![
            Annotation::Access {
                read: vec!["analyst".to_string()],
                write: vec!["analyst".to_string()],
                delete: vec![],
                cross_tenant_read: vec![],
            },
            Annotation::Export {
                formats: vec![ExportFormat::Csv, ExportFormat::Ndjson],
                bundle_files: false,
                max_rows: 100,
            },
        ],
    )
    .unwrap()
}

async fn provision(backend: &Arc<SurrealBackend>, schema: &SchemaDefinition) {
    let plan = schema_forge_core::migration::DiffEngine::create_new(schema);
    backend
        .apply_migration(&schema.name, &plan.steps)
        .await
        .expect("migration");
    backend
        .store_schema_metadata(schema)
        .await
        .expect("metadata");
}

/// Build state + a seeded `Subject` table; returns the state and the seeding
/// admin app so callers can drive both the actor directly and the HTTP routes.
async fn seeded_state(
    schema: SchemaDefinition,
    rows: &[serde_json::Value],
) -> AppState<SchemaForgeConfig> {
    let backend = Arc::new(
        SurrealBackend::connect_memory("test", "test")
            .await
            .expect("mem surreal"),
    );
    provision(&backend, &schema).await;

    let mut registry = HashMap::new();
    registry.insert(schema.name.as_str().to_string(), schema.clone());
    let state = build_state(backend, registry).await;

    let admin = app_with_claims(state.clone(), make_claims(&["platform_admin"]));
    let path = format!("/schemas/{}/entities", schema.name.as_str());
    for row in rows {
        let (status, json) = raw_request(&admin, Method::POST, &path, Some(row.clone())).await;
        assert_eq!(status, StatusCode::CREATED, "seed failed: {json}");
    }
    state
}

/// Pull the inputs `materialize_export` needs out of the live actor so a test can
/// assemble an `ExportJobSpec` exactly as the route handler would.
async fn job_inputs(
    state: &AppState<SchemaForgeConfig>,
    schema: &str,
) -> (
    ActorHandle,
    SchemaDefinition,
    Arc<schema_forge_acton::authz::PolicyStore>,
    Option<schema_forge_backend::tenant::TenantConfig>,
    Option<Arc<dyn schema_forge_backend::auth::RecordAccessPolicy>>,
) {
    let forge = state.actor::<ForgeActor>().expect("ForgeActor").clone();

    let (tx, rx) = oneshot::channel();
    forge
        .send(schema_forge_acton::messages::GetSchema {
            name: schema.to_string(),
            reply: ReplyChannel::new(tx),
        })
        .await;
    let schema_def = rx.await.unwrap().expect("schema registered");

    let (tx, rx) = oneshot::channel();
    forge.send(GetPolicyStore { reply: ReplyChannel::new(tx) }).await;
    let policy_store = rx.await.unwrap().expect("policy store");

    let (tx, rx) = oneshot::channel();
    forge.send(GetTenantConfig { reply: ReplyChannel::new(tx) }).await;
    let tenant_config = rx.await.unwrap();

    let (tx, rx) = oneshot::channel();
    forge
        .send(GetRecordAccessPolicy { reply: ReplyChannel::new(tx) })
        .await;
    let record_access_policy = rx.await.unwrap();

    (forge, schema_def, policy_store, tenant_config, record_access_policy)
}

async fn poll_until_terminal(
    job_actor: &ActorHandle,
    job_id: &str,
) -> schema_forge_acton::export_job::ExportJobRecord {
    for _ in 0..200 {
        let (tx, rx) = oneshot::channel();
        job_actor
            .send(GetExportJob {
                job_id: job_id.to_string(),
                reply: ReplyChannel::new(tx),
            })
            .await;
        if let Some(record) = rx.await.unwrap() {
            if matches!(
                record.status,
                ExportJobStatus::Complete | ExportJobStatus::Failed
            ) {
                return record;
            }
        }
        tokio::time::sleep(Duration::from_millis(10)).await;
    }
    panic!("export job did not reach a terminal state in time");
}

